window.S17Page={"sceneId":"t5","caseId":"s17x-t5-tank-level-crosscheck","name":"储罐液位与泄漏智能监控","title":"储罐液位监控：图像读数怎样与雷达互相核对","summary":"固定机位图像里的液面边界与雷达读数来自不同测量链。先从像素中提取边界，再换算液位，与雷达并列核查，避免把某个单一读数当成唯一依据。","directory":"expansion-cases","caseVersion":"1.0.1","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){"use strict";function mean(a){return a.reduce((s,x)=>s+x,0)/a.length}function mae(a,b){return mean(a.map((v,i)=>Math.abs(v-b[i])))}function reg(x,y){let xm=mean(x),ym=mean(y);let b=x.reduce((s,v,i)=>s+(v-xm)*(y[i]-ym),0)/(x.reduce((s,v)=>s+(v-xm)**2,0)||1);return {a:ym-b*xm,b}}function median(a){a=a.slice().sort((x,y)=>x-y);return a[Math.floor(a.length/2)]}function rng(seed){return ()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296}}function image(h,fog,seed,light){let R=rng(seed),edge=Math.round((1-h/10)*99);return Array.from({length:100},(_,y)=>Array.from({length:32},(_,x)=>{let shade=x>=((seed%3)*7+5)&&x<=((seed%3)*7+10)&&y>15&&y<55?-80:0;return Math.max(0,Math.min(255,(y>=edge?62:173)+light+y*.18+(R()-.5)*fog*55+shade))}))}function predict(px){let profile=px.map(median),g=profile.map((v,i)=>i>2&&i<97?Math.abs(profile[i+2]-profile[i-2]):0),peak=g.indexOf(Math.max(...g));let indices=g.map((v,i)=>({v,i})).filter(x=>Math.abs(x.i-peak)<=2);let w=indices.reduce((s,x)=>s+x.v,0);let row=indices.reduce((s,x)=>s+x.v*x.i,0)/(w||1);let col=px.map(r=>r[16]);let by=col.findIndex(v=>v<105);return{h:10*(1-row/99),baseline:10*(1-(by<0?99:by)/99),profile,gradient:g,strength:g[peak],row}}function run(p){let px=image(p.level,p.fog,525,5),out=predict(px),radar=p.level+p.radarBias;let refs=Array.from({length:18},(_,i)=>2+(i*7%14)/2),est=refs.map((h,i)=>predict(image(h,p.fog,600+i,(i%5-2)*18)));let diff=Math.abs(out.h-radar);return{summary:diff>.6?'两条测量链差 '+diff.toFixed(2)+' m，进入交叉核查；先看图像边界清晰度，再核对雷达记录。':'视觉与雷达相差 '+diff.toFixed(2)+' m，在本例 0.6 m 一致性窗口内。',metrics:[['当前视觉高度',out.h.toFixed(2)+' m'],['雷达高度',radar.toFixed(2)+' m'],['当前检测行 y',out.row.toFixed(2)],['边界四行跨度灰度差',out.strength.toFixed(1)+' 灰度级'],['18 帧视觉 MAE',mae(est.map(x=>x.h),refs).toFixed(3)+' m'],['单列阈值 MAE',mae(est.map(x=>x.baseline),refs).toFixed(3)+' m']],charts:[{title:'观察窗逐行灰度：液面位置来自强度转折',xlabel:'像素行 y（顶部至底部）',ylabel:'灰度 0～255',series:[{name:'每行中位数',y:out.profile},{name:'梯度强度',y:out.gradient}]},{indexStart:1,title:'18 帧高度识别：同一评价片段',xlabel:'帧序号',ylabel:'m',series:[{name:'梯度视觉',y:est.map(x=>x.h)},{name:'单列阈值',y:est.map(x=>x.baseline)},{name:'独立参考',y:refs}]}],headers:['片段帧','梯度高度 m','阈值高度 m','事后参考 m'],rows:est.map((x,i)=>[i+1,x.h.toFixed(2),x.baseline.toFixed(2),refs[i].toFixed(2)]),pixels:px,edgeRow:out.row,boundaryStrength:out.strength,radar,visualHeight:out.h,denominator:18,referenceUsedOnlyInEvaluation:true}};g.TransportEngine={run:run};})(globalThis);

